    async def review_mission_objective(self, mission_id: str, objective_id: str, body: Union[_m.ReviewMissionObjectiveRequest, Dict[str, Any]], *, request_options: Optional[RequestOptions] = None) -> _m.Objective:
        """Accept, revise or reject an objective's result

        A person's verdict on a result held at `awaiting_review` (an objective with
        `review_required`). `accept` completes it and the mission moves on; `revise` sends it back —
        the agent is re-run with its previous version and `feedback`, which is not counted as a
        failed attempt (at most 10 revisions, then `revision_limit_10`); `reject` fails it with
        `abort_reason: rejected_by_person`. Answers the objective with `review` set; the mission
        clears it once acted on. `409` unless the objective is `awaiting_review`, and while an
        earlier verdict is still unread; `422` for an unknown `decision`, for `revise` without
        `feedback`, and for feedback over 10 000 characters; `404` for a mission or objective that
        does not exist or does not belong to it. Only POST is allowed (`405`). Since 2026-10-12.

        MEF is gated twice: globally by the server flag and per tenant by `mef_config.enabled`. When
        either is off the route answers **404** with a plain body.

        `POST /api/v1/missions/{missionId}/objectives/{objectiveId}/review`

        Required scopes: `agents:write`.
        """
        return _cast("_m.Objective", await self._client._request(
            "POST",
            f"/api/v1/missions/{_segment(mission_id)}/objectives/{_segment(objective_id)}/review",
            body=_Body(body),
            idempotent=True,
            response=_Response(type=_m.Objective),
            request_options=request_options,
        ))

    async def run(self, mission_id: str, *, request_options: Optional[RequestOptions] = None) -> _m.RunMissionResponse:
        """Start executing a mission

        Answers immediately; the executor walk is detached. Watch progress on the event stream or by
        polling the mission — this endpoint used to run the walk synchronously and was killed by the
        edge proxy's two-minute timeout before a multi-objective mission could finish.

        A second call while a walk is in flight is a no-op that answers **200** with `accepted:
        false` and `already_running: true`, not 202 and not an error: the executor is not safe under
        concurrent walks over one mission. Requires status `executing` — anything else is 409,
        including a mission still waiting on its authorization gate.

        MEF is gated twice: globally by the server flag and per tenant by `mef_config.enabled`. When
        either is off the route answers **404** with a plain body — deliberately the same answer as
        a mission that does not exist, so an opted-out tenant cannot discover the surface.

        `POST /api/v1/missions/{missionId}/run`

        Required scopes: `agents:write`.
        """
        return _cast("_m.RunMissionResponse", await self._client._request(
            "POST",
            f"/api/v1/missions/{_segment(mission_id)}/run",
            idempotent=True,
            response=_Response(type=_m.RunMissionResponse),
            request_options=request_options,
        ))

    async def start_mission(self, body: Union[_m.StartMissionRequest, Dict[str, Any]], *, request_options: Optional[RequestOptions] = None) -> _m.MissionStartResponse:
        """Start a mission

        Two ways in. Supply `plan` and it is used as written. While it executes, an objective whose
        run stops for a person (an approval, a question, a pause) is WAITED ON until the person
        decides — it shows in `GET /analytics/inbox` — and is not counted as a failed attempt
        (before 2026-10-12 it was, and was re-dispatched until the mission failed). A person's
        rejection ends that objective at once with `abort_reason: rejected_by_person` rather than
        putting the refused work back in front of them. Omit it and the server's LLM planner
        decomposes `goal`, which requires `available_agents` and a planner wired on the server —
        without one the request is rejected with 400 rather than silently producing an empty
        mission.

        MEF is gated twice: globally by the server flag and per tenant by `mef_config.enabled`. When
        either is off the route answers **404** with a plain body — deliberately the same answer as
        a mission that does not exist, so an opted-out tenant cannot discover the surface.

        `POST /api/v1/missions`

        Required scopes: `agents:write`.
        """
        return _cast("_m.MissionStartResponse", await self._client._request(
            "POST",
            "/api/v1/missions",
            body=_Body(body),
            idempotent=True,
            response=_Response(type=_m.MissionStartResponse),
            request_options=request_options,
        ))

    def stream_mission_events(self, mission_id: str, *, request_options: Optional[RequestOptions] = None) -> AsyncEventStream:
        """Stream mission progress (SSE)

        Server-sent events, poll-backed. Event names: `connected` (handshake), `mission` (snapshot
        on connect), `status_change` (`from`, `to`, `outcome`, `result_summary`, and since
        2026-09-23 `result_code`/`result_details` when set), `checkpoint_added` (one per new
        checkpoint id), `aar_finalized`, and `terminal` as the last event before the server closes.
        The stream closes itself on a terminal status so a client stops reconnecting, and is capped
        at 15 minutes per connection regardless — a long mission is expected to reconnect.

        MEF is gated twice: globally by the server flag and per tenant by `mef_config.enabled`. When
        either is off the route answers **404** with a plain body — deliberately the same answer as
        a mission that does not exist, so an opted-out tenant cannot discover the surface.

        `GET /api/v1/missions/{missionId}/events`

        Required scopes: `agents:read`.

        Returns a server-sent event stream; iterate it with `async for`.
        """
        return self._client._stream(
            f"/api/v1/missions/{_segment(mission_id)}/events",
            request_options=request_options,
        )

    async def update_mission_objective(self, mission_id: str, objective_id: str, body: Union[_m.UpdateMissionObjectiveRequest, Dict[str, Any]], *, request_options: Optional[RequestOptions] = None) -> _m.Objective:
        """Edit one objective's configuration

        Configuration only: assignment, budget ceilings, deadline, rules of engagement, commander's
        intent, decision points, priority and text. Lifecycle stays with the executor — there is no
        way to set `status` from here. An empty patch is rejected with 422 rather than answering 200
        for a write that did nothing. Sending `assigned_agent_id` or `assigned_team_id` as an empty
        string clears the assignment.

        MEF is gated twice: globally by the server flag and per tenant by `mef_config.enabled`. When
        either is off the route answers **404** with a plain body — deliberately the same answer as
        a mission that does not exist, so an opted-out tenant cannot discover the surface.

        WRITE SEMANTICS: mixed. An omitted field keeps its stored value. `budget` merges one level
        deep over the stored budget, while `roe`, `decision_points` and `success_criteria` are
        replaced whole when sent.

        `PATCH /api/v1/missions/{missionId}/objectives/{objectiveId}`

        Required scopes: `agents:write`.
        """
        return _cast("_m.Objective", await self._client._request(
            "PATCH",
            f"/api/v1/missions/{_segment(mission_id)}/objectives/{_segment(objective_id)}",
            body=_Body(body),
            idempotent=True,
            response=_Response(type=_m.Objective),
            request_options=request_options,
        ))
